+class ContactForm {
+    constructor(formId) {
+        this.form = document.getElementById(formId);
+        this.successMessage = document.getElementById('successMessage');
+        this.fields = {
+            fullName: document.getElementById('fullName'),
+            email: document.getElementById('email'),
+            phone: document.getElementById('phone')
+        };
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        this.setupFieldValidation();
+    }
+
+    setupFieldValidation() {
+        this.fields.fullName.addEventListener('blur', () => this.validateField('fullName'));
+        this.fields.email.addEventListener('blur', () => this.validateField('email'));
+        this.fields.phone.addEventListener('blur', () => this.validateField('phone'));
+    }
+
+    validateField(fieldName) {
+        const field = this.fields[fieldName];
+        const errorSpan = field.parentElement.querySelector('.field-error');
+        let isValid = true;
+        let errorMessage = '';
+
+        switch (fieldName) {
+            case 'fullName':
+                if (!field.value.trim()) {
+                    isValid = false;
+                    errorMessage = 'Full name is required';
+                } else if (field.value.trim().length < 2) {
+                    isValid = false;
+                    errorMessage = 'Full name must be at least 2 characters';
+                }
+                break;
+
+            case 'email':
+                if (!field.value.trim()) {
+                    isValid = false;
+                    errorMessage = 'Email address is required';
+                } else if (!this.isValidEmail(field.value)) {
+                    isValid = false;
+                    errorMessage = 'Please enter a valid email address';
+                }
+                break;
+
+            case 'phone':
+                if (field.value.trim() && !this.isValidPhone(field.value)) {
+                    isValid = false;
+                    errorMessage = 'Please enter a valid phone number';
+                }
+                break;
+        }
+
+        this.updateFieldUI(field, isValid, errorMessage, errorSpan);
+        return isValid;
+    }
+
+    updateFieldUI(field, isValid, errorMessage, errorSpan) {
+        field.classList.remove('error', 'success');
+        errorSpan.textContent = '';
+
+        if (field.value.trim() === '') {
+            field.classList.remove('error', 'success');
+        } else if (isValid) {
+            field.classList.add('success');
+            field.classList.remove('error');
+        } else {
+            field.classList.add('error');
+            field.classList.remove('success');
+            errorSpan.textContent = errorMessage;
+        }
+    }
+
+    isValidEmail(email) {
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        return emailRegex.test(email);
+    }
+
+    isValidPhone(phone) {
+        const phoneRegex = /^[\d\s\-().+]*$/;
+        if (!phoneRegex.test(phone)) return false;
+
+        const digitsOnly = phone.replace(/\D/g, '');
+        return digitsOnly.length >= 10 && digitsOnly.length <= 15;
+    }
+
+    validateForm() {
+        let isValid = true;
+
+        isValid = this.validateField('fullName') && isValid;
+        isValid = this.validateField('email') && isValid;
+        isValid = this.validateField('phone') && isValid;
+
+        return isValid;
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        if (!this.validateForm()) {
+            return;
+        }
+
+        const formData = {
+            fullName: this.fields.fullName.value.trim(),
+            email: this.fields.email.value.trim(),
+            phone: this.fields.phone.value.trim()
+        };
+
+        this.submitForm(formData);
+    }
+
+    submitForm(formData) {
+        const submitButton = this.form.querySelector('.submit-button');
+        submitButton.disabled = true;
+        submitButton.textContent = 'Sending...';
+
+        setTimeout(() => {
+            this.showSuccessMessage();
+            this.resetForm();
+            submitButton.disabled = false;
+            submitButton.textContent = 'Send Message';
+        }, 1000);
+    }
+
+    showSuccessMessage() {
+        this.successMessage.textContent = 'Thank you! Your message has been sent successfully.';
+        this.successMessage.classList.add('show');
+
+        setTimeout(() => {
+            this.successMessage.classList.remove('show');
+            this.successMessage.textContent = '';
+        }, 5000);
+    }
+
+    resetForm() {
+        this.form.reset();
+        Object.values(this.fields).forEach(field => {
+            field.classList.remove('error', 'success');
+            const errorSpan = field.parentElement.querySelector('.field-error');
+            if (errorSpan) errorSpan.textContent = '';
+        });
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm('contactForm');
+});
+
